Хорошо, l10n сгенерировался успешно, ключ `showMore` доступен через `context.loc.showMore`. Теперь нужно модифицировать страницу.

План изменений:
1. Добавить переменные для отслеживания состояния пагинации (`_isLoadingMore`, `_hasMore`)
2. Создать метод `_loadNextPage()` который запрашивает следующую страницу и добавляет элементы к `_allCurrencies` (а не заменяет)
3. Обновить `_filterCurrencies` чтобы фильтровался список на основе всего `_allCurrencies` (или текущего отфильтрованного?) — нужно подумать
4. Добавить кнопку "Показать ещё" под списком, которая вызывает `_loadNextPage()`

Важные моменты из контракта v2:
- `CurrencyPageRequest(base: 'USD', page: N, pageSize: 20)` — base должен быть 'USD'
- `page` с 0, конец пагинации — `hasMore == false`
- Элементы ДОБАВЛЯЮТСЯ к списку (не заменяют)

Сейчас в коде используется `CurrencyPageRequest()` без параметров, что значит `base: 'EUR'`. Нужно изменить на `base: 'USD'`.

Для фильтрации: при загрузке новых элементов нужно переприменить текущий фильтр. Логично хранить текущий query и применять его к новому списку.

Или можно так:
- `_allCurrencies` — полный список всех загруженных валют (для поиска)
- После загрузки новой страницы добавляем элементы в `_allCurrencies`, затем заново применяем фильтр
- Или: фильтровать всегда от `_allCurrencies`

Давай сделаю так:
1. `String _searchQuery = '';` — текущий запрос поиска
2. Метод `_applyFilter()` — применяет поиск к `_allCurrencies` и обновляет `_filteredCurrenciesNotifier`
3. `_filterCurrencies(String query)` сохраняет query и вызывает `_applyFilter()`
4. `_loadNextPage()` загружает страницу, добавляет в `_allCurrencies`, затем снова вызывает `_applyFilter()`

Также нужно добавить кнопку под списком (не внутри Expanded), которая видна только если `!_isLoadingMore && _hasMore`.

Давай напишу код:

```dart
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  String _searchQuery = '';

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = value;
      _currentPage = page.page;
      _hasMore = page.hasMore;
      _applyFilter();

      _fadeController.forward(); // запускаем анимацию

      currencyRepository.saveCurrencyList(value);

      return value;
    });
  }

  void _applyFilter() {
    final String lowerQuery = _searchQuery.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _searchQuery = query;
    _applyFilter();
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final nextPage = _currentPage + 1;

    try {
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: nextPage, pageSize: 20));

      if (mounted) {
        setState(() {
          _allCurrencies.addAll(page.items);
          _currentPage = page.page;
          _hasMore = page.hasMore;
          currencyRepository.saveCurrencyList(page.items);
        });

        // Переприменяем текущий фильтр к обновлённому списку
        if (mounted) {
          _applyFilter();
        }
      }
    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length,
                        itemBuilder: (BuildContext context, int index) {
                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, _hasMore && !_isLoadingMore ? 40 : 0),
                      );
                    },
                  ),
                ),
                if (_hasMore || _isLoadingMore)
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 16),
                    child: Center(
                      child: _isLoadingMore
                          ? const CircularProgressIndicator()
                          : ElevatedButton(
                              onPressed: _loadNextPage,
                              child: Text(context.loc.showMore),
                            ),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}
```

Подожди, у меня проблема с `_filteredCurrenciesNotifier` — он инициализируется в `_initData()`, но используется до этого. Нужно инициализировать его в `initState`.

Давай исправлю:

```dart
